import java.nio.file.*;import org.json.*;
public final class AbyssUnitTest {
 public static void main(String[] args)throws Exception{JSONObject f=new JSONObject(new String(Files.readAllBytes(Paths.get("abyss-unit-fixture.json")),"UTF-8")),data=AbyssClient.config(f.getString("html"),f.getString("embed"));if(!data.getJSONObject("media").getJSONObject("mp4").getJSONArray("sources").getJSONObject(0).getString("codec").equals("h264"))throw new AssertionError("Media config decrypt");String token=AbyssClient.token(f.getString("path"),f.getLong("size"));if(!token.equals(f.getString("token")))throw new AssertionError("Token mismatch: "+token);try{AbyssClient.config(f.getString("html"),"https://player.abyssplayer.com/wrong1234");throw new AssertionError("Video identity accepted");}catch(AssertionError e){throw e;}catch(Exception expected){}
  JSONObject source=data.getJSONObject("media").getJSONObject("mp4").getJSONArray("sources").getJSONObject(0);if(!AbyssClient.mediaUrl(data,source).startsWith("https://testcdn.sssrr.org/sora/"))throw new AssertionError("Media URL construction");data.getJSONObject("media").getJSONObject("mp4").put("domains",new JSONArray().put("testcdn.sssrr.org.evil.invalid"));try{AbyssClient.mediaUrl(data,source);throw new AssertionError("Unrelated media host accepted");}catch(AssertionError e){throw e;}catch(Exception expected){}
  NativeCatalog.Candidate wrong=new NativeCatalog.Candidate("Abyss","https://deseneledublate.com/desen/unknown/","","ROMANA",f.getString("embed"),new JSONObject().put("durationSeconds",6000));try{AbyssClient.resolve(wrong);throw new AssertionError("Other site's audio provenance accepted");}catch(AssertionError e){throw e;}catch(Exception expected){if(!expected.getMessage().contains("provenance"))throw expected;}
  if(AbyssClient.mediaHeaders(f.getString("embed")).containsKey("Origin"))throw new AssertionError("Incorrect media Origin header");System.out.println("PASS independent AES-CTR, numeric-key encoding, double-base64 token, video identity, media host/provenance and native headers");}
}
